/* THROWAWAY SPIKE (#6, #23): build with -DPROBE=n to time one push shape. */
#ifndef PROBE
#define PROBE 0
#endif
static uint16_t *probeStage;

static void probePush() {
  int n = PROBE;
  if (n == 2) {
    M5.Display.pushImage(0, 0, kSize, kSize / 2, canvas.px);
  } else if (n == 3) {
    for (int y = 0; y < kSize / 2; y++)
      M5.Display.pushImage(116, 116 + y, kSize / 2, 1,
                           canvas.px + (116 + y) * kSize + 116);
  } else if (n == 4) {
    if (!probeStage)
      probeStage = (uint16_t *)ps_malloc(kSize * kSize / 4 * sizeof(uint16_t));
    for (int y = 0; y < kSize / 2; y++)
      memcpy(probeStage + y * (kSize / 2), canvas.px + (116 + y) * kSize + 116,
             (kSize / 2) * sizeof(uint16_t));
    M5.Display.pushImage(116, 116, kSize / 2, kSize / 2, probeStage);
  } else if (n == 5) {
    float r = kSize / 2.0f;
    for (int y = 0; y < kSize; y++) {
      float dy = y + 0.5f - r;
      int half = (int)sqrtf(r * r - dy * dy);
      int x0 = (int)r - half;
      M5.Display.pushImage(x0, y, 2 * half, 1, canvas.px + y * kSize + x0);
    }
  } else if (n == 6) {
    for (int y = 0; y < kSize; y++)
      M5.Display.pushImage(0, y, kSize, 1, canvas.px + y * kSize);
  } else {
    M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
  }
}

