/* THROWAWAY: how much of the canvas does each hack change per step? */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"

int main(int argc, char **argv) {
  int frames = argc > 1 ? atoi(argv[1]) : 600;
  const int W = 466, H = 466, N = W * H;
  const double per_px = 0.143, per_call = 12.0, full_us = 31100.0;
  for (int i = 0; i < g_hack_count; i++) {
    Canvas cv;
    canvas_init(&cv, W, H, malloc);
    uint16_t *prev = malloc(N * 2);
    HackRunner *r = runner_create(&cv);
    runner_start(r, i);
    memcpy(prev, cv.px, N * 2);
    double bbox_area = 0, span_area = 0, bbox_us = 0, span_us = 0, changed = 0;
    int idle = 0;
    for (int f = 0; f < frames; f++) {
      runner_step(r);
      int x0 = W, x1 = -1, y0 = H, y1 = -1;
      long nchg = 0, spans = 0;
      double rowspan_us = 0;
      for (int y = 0; y < H; y++) {
        int rx0 = W, rx1 = -1;
        for (int x = 0; x < W; x++)
          if (cv.px[y * W + x] != prev[y * W + x]) {
            if (x < rx0) rx0 = x;
            rx1 = x;
            nchg++;
          }
        if (rx1 >= 0) {
          if (rx0 < x0) x0 = rx0;
          if (rx1 > x1) x1 = rx1;
          if (y < y0) y0 = y;
          y1 = y;
          spans += rx1 - rx0 + 1;
          rowspan_us += per_call + per_px * (rx1 - rx0 + 1);
        }
      }
      memcpy(prev, cv.px, N * 2);
      if (x1 < 0) {
        idle++;
        continue;
      }
      int bw = x1 - x0 + 1, bh = y1 - y0 + 1;
      bbox_area += (double)bw * bh / N;
      span_area += (double)spans / N;
      changed += (double)nchg / N;
      bbox_us += bw >= 382 ? bh * W * per_px : bh * (per_px * bw + per_call);
      span_us += rowspan_us;
    }
    printf("%-14s idle %3.0f%%  changed %5.1f%%  bbox %5.1f%%  rowspan %5.1f%%  "
           "push bbox %5.1f ms  rowspan %5.1f ms  (full 31.1)\n",
           g_hacks[i]->name, 100.0 * idle / frames, 100 * changed / frames,
           100 * bbox_area / frames, 100 * span_area / frames,
           bbox_us / frames / 1000, span_us / frames / 1000);
    (void)full_us;
    runner_destroy(r);
    canvas_free(&cv);
    free(prev);
  }
  return 0;
}
